var log = new List<string>();
Func<CreateUser, Result> handler = cmd => { log.Add("handler"); return Result.Ok(); };

var behaviors = new List<Func<CreateUser, Func<Result>, Result>>
{
    (cmd, next) => { log.Add("logging in"); var r = next(); log.Add($"logging out ok={r.IsSuccess}"); return r; },
    (cmd, next) => string.IsNullOrWhiteSpace(cmd.Email)
        ? Result.Fail("email required")
        : next(),
    (cmd, next) => { log.Add("begin tx"); var r = next(); log.Add("commit"); return r; },
};

Result Send(CreateUser cmd)
{
    Func<Result> pipeline = () => handler(cmd);
    for (int i = behaviors.Count - 1; i >= 0; i--)
    {
        var behavior = behaviors[i];
        var next = pipeline;
        pipeline = () => behavior(cmd, next);
    }
    return pipeline();
}

