interface IDomainEvent;
record OrderPlaced(int Attempt) : IDomainEvent;

abstract class AggregateRoot
{
    private readonly List<IDomainEvent> _events = new();
    public IReadOnlyCollection<IDomainEvent> DomainEvents => _events;
    protected void Raise(IDomainEvent e) => _events.Add(e);
    public void ClearDomainEvents() => _events.Clear();
}

class Order : AggregateRoot
{
    private int _attempts;
    public bool IsPlaced { get; private set; }
    public void Place()
    {
        _attempts++;
        if (IsPlaced) return;
        IsPlaced = true;
        Raise(new OrderPlaced(_attempts));
    }
}

class FakeContext
{
    private readonly List<AggregateRoot> _tracked = new();
    private int _saves;
    public void Track(AggregateRoot a) => _tracked.Add(a);
    public void SaveChanges()
    {
        _saves++;
        var events = _tracked.SelectMany(a => a.DomainEvents).ToList();
        _tracked.ForEach(a => a.ClearDomainEvents());
        foreach (var e in events) Console.WriteLine($"save {_saves}: dispatch {e}");
        Console.WriteLine($"save {_saves}: {events.Count} event(s)");
    }
}

