static string Register(string email, int age) =>
    ValidateEmail(email)
        .Bind(e => ValidateAge(age).Map(a => $"{e} ({a})"))
        .Match(ok => $"created {ok}", err => $"rejected: {err}");

static Result<string> ValidateEmail(string email) =>
    email.Contains('@') ? Result<string>.Ok(email) : Result<string>.Fail("bad email");

static Result<int> ValidateAge(int age) =>
    age >= 18 ? Result<int>.Ok(age) : Result<int>.Fail("too young");

readonly record struct Result<T>(bool IsSuccess, T? Value, string? Error)
{
    public static Result<T> Ok(T value) => new(true, value, null);
    public static Result<T> Fail(string error) => new(false, default, error);

    public Result<TOut> Bind<TOut>(Func<T, Result<TOut>> next) =>
        IsSuccess ? next(Value!) : Result<TOut>.Fail(Error!);

    public Result<TOut> Map<TOut>(Func<T, TOut> map) =>
        IsSuccess ? Result<TOut>.Ok(map(Value!)) : Result<TOut>.Fail(Error!);

    public TOut Match<TOut>(Func<T, TOut> ok, Func<string, TOut> fail) =>
        IsSuccess ? ok(Value!) : fail(Error!);
}

var breaker = new CircuitBreaker(failureThreshold: 2, breakSeconds: 5);
var dependencyUp = false;

foreach (var second in new[] { 0, 1, 3, 6, 9, 12 })
{
    if (second == 12) dependencyUp = true;
    var outcome = breaker.Execute(second, () => dependencyUp);
    Console.WriteLine($"t={second} {outcome} -> {breaker.State}");
}

class CircuitBreaker(int failureThreshold, int breakSeconds)
{
    private int _failures;
    private int _openedAt;
    public string State { get; private set; } = "Closed";

    public string Execute(int now, Func<bool> call)
    {
        if (State == "Open")
        {
            if (now - _openedAt < breakSeconds) return "rejected";
            State = "HalfOpen";
        }

        if (call())
        {
            _failures = 0;
            State = "Closed";
            return "ok";
        }

        _failures++;
        if (State == "HalfOpen" || _failures >= failureThreshold)
        {
            State = "Open";
            _openedAt = now;
        }
        return "failed";
    }
}

