class OrderSaga
{
    public string State { get; private set; } = "Initial";

    public void Handle(string message)
    {
        var (next, action) = (State, message) switch
        {
            ("Initial", "OrderSubmitted") => ("AwaitingStock", "reserve stock"),
            ("AwaitingStock", "StockReserved") => ("AwaitingPayment", "capture payment"),
            ("AwaitingPayment", "PaymentCaptured") => ("Completed", "ship order"),
            ("AwaitingPayment", "PaymentFailed") => ("Cancelled", "release stock"),
            _ => (State, "ignored"),
        };
        Console.WriteLine($"{message}: {State} -> {next} ({action})");
        State = next;
    }
}
